import{_ as t}from"./chunks/benchmark.JDxUlm17.js";import{_ as a,o as r,c as s,ag as o}from"./chunks/framework.DqVSm8kp.js";const p=JSON.parse('{"title":"Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/benchmark.md","filePath":"en/guide/benchmark.md"}'),n={name:"en/guide/benchmark.md"};function i(l,e,c,d,u,h){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="benchmark" tabindex="-1">Benchmark <a class="header-anchor" href="#benchmark" aria-label="Permalink to &quot;Benchmark&quot;">​</a></h1><p>The Benchmark page runs standardized evaluations against your local models using real token logprobs, giving you objective performance data.</p><p><strong>Sidebar item:</strong> Benchmark <strong>Route:</strong> <code>/benchmark</code></p><p><img src="'+t+'" alt="Benchmark interface"></p><h2 id="what-is-the-surgical-benchmark" tabindex="-1">What is the Surgical Benchmark? <a class="header-anchor" href="#what-is-the-surgical-benchmark" aria-label="Permalink to &quot;What is the Surgical Benchmark?&quot;">​</a></h2><p>Unlike typical benchmarks that just check if the answer is correct, LLMxRay&#39;s Surgical Benchmark captures <strong>real token logprobs</strong> via Ollama&#39;s OpenAI-compatible endpoint (<code>/v1/chat/completions</code>). This gives you genuine confidence data for each answer, not just accuracy.</p><h2 id="built-in-test-suites" tabindex="-1">Built-in Test Suites <a class="header-anchor" href="#built-in-test-suites" aria-label="Permalink to &quot;Built-in Test Suites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Questions</th><th>What it tests</th></tr></thead><tbody><tr><td><strong>ARC</strong></td><td>Science reasoning</td><td>Grade-school science questions</td></tr><tr><td><strong>GSM8K</strong></td><td>Math word problems</td><td>Multi-step arithmetic reasoning</td></tr><tr><td><strong>HellaSwag</strong></td><td>Sentence completion</td><td>Common-sense reasoning</td></tr><tr><td><strong>MMLU-Pro</strong></td><td>Multi-subject</td><td>Broad academic knowledge across domains</td></tr><tr><td><strong>TruthfulQA</strong></td><td>Truthfulness</td><td>Resistance to common misconceptions</td></tr></tbody></table><h2 id="running-a-benchmark" tabindex="-1">Running a Benchmark <a class="header-anchor" href="#running-a-benchmark" aria-label="Permalink to &quot;Running a Benchmark&quot;">​</a></h2><ol><li>Select a <strong>model</strong> from the dropdown.</li><li>Choose one or more <strong>test suites</strong>.</li><li>Click <strong>Run</strong>. The benchmark streams results in real time.</li></ol><p>During execution you can see:</p><ul><li><strong>Live progress</strong> — Question count, current accuracy</li><li><strong>Per-question results</strong> — Correct/incorrect, model&#39;s answer, confidence scores</li><li><strong>Latency data</strong> — TTFT and tokens/sec per question</li></ul><h2 id="thinking-models" tabindex="-1">Thinking Models <a class="header-anchor" href="#thinking-models" aria-label="Permalink to &quot;Thinking Models&quot;">​</a></h2><p>For reasoning models like DeepSeek-R1, the benchmark uses <strong>dynamic token budgets</strong> — allowing the model more tokens for its <code>&lt;think&gt;</code> blocks without counting them against the answer. This ensures thinking models aren&#39;t penalized for showing their work.</p><h2 id="results-visualization" tabindex="-1">Results Visualization <a class="header-anchor" href="#results-visualization" aria-label="Permalink to &quot;Results Visualization&quot;">​</a></h2><p>After completion, results are displayed as:</p><ul><li><strong>Accuracy score</strong> — Overall percentage correct</li><li><strong>Per-category breakdown</strong> — Accuracy by subject area within each suite</li><li><strong>Radar chart</strong> — Visual comparison across categories</li><li><strong>Confidence distribution</strong> — Histogram of logprob-based confidence scores</li></ul><h2 id="comparing-results" tabindex="-1">Comparing Results <a class="header-anchor" href="#comparing-results" aria-label="Permalink to &quot;Comparing Results&quot;">​</a></h2><p>Run the same suite on multiple models to compare:</p><ul><li>Which model is most accurate on which subjects</li><li>Confidence calibration — does high confidence correlate with correct answers?</li><li>Speed vs. accuracy trade-offs</li></ul><p>Results are stored in IndexedDB so you can compare across sessions.</p><h2 id="custom-suites" tabindex="-1">Custom Suites <a class="header-anchor" href="#custom-suites" aria-label="Permalink to &quot;Custom Suites&quot;">​</a></h2><p>Click <strong>Import</strong> to load a custom benchmark suite. The expected format is a JSON file with:</p><ul><li>Suite name and description</li><li>Array of questions, each with: question text, answer choices, correct answer index, and optional category</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Logprobs require the <code>/v1</code> endpoint</strong> — This uses Ollama&#39;s OpenAI-compatible API, not the native <code>/api</code> endpoint.</li><li><strong>Smaller suites first</strong> — Start with a subset to estimate how long a full run will take.</li><li><strong>Resume support</strong> — If a benchmark is interrupted, you can resume from where it left off.</li><li><strong>Compare quantizations</strong> — Run the same model at Q4 and Q8 to see the accuracy impact.</li></ul>',26)])])}const b=a(n,[["render",i]]);export{p as __pageData,b as default};
